import React, { useState, useRef, useEffect } from 'react';

export default function SlotControl({ value, onChange, choices, locale }) {
  const [open, setOpen] = useState(false);
  const gridRef = useRef(null);
  const selected = choices.find((choice) => choice.date === value);

  useEffect(() => {
    if (open && gridRef.current) {
      const firstAvailable = gridRef.current.querySelector('[data-date]:not(.unavailable)');
      if (firstAvailable) firstAvailable.focus();
    }
  }, [open]);

  const handleKeyDown = (e, choice) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (!choice.unavailable) {
        onChange(choice.date);
        setOpen(false);
      }
    } else if (e.key === 'ArrowRight' || e.key === 'ArrowLeft' || e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      const cells = Array.from(gridRef.current?.querySelectorAll('[data-date]:not(.unavailable)') || []);
      const idx = cells.findIndex((c) => c === e.target);
      if (idx === -1) return;
      let nextIdx = idx;
      if (e.key === 'ArrowRight') nextIdx = (idx + 1) % cells.length;
      else if (e.key === 'ArrowLeft') nextIdx = (idx - 1 + cells.length) % cells.length;
      else if (e.key === 'ArrowDown') nextIdx = Math.min(idx + 4, cells.length - 1);
      else if (e.key === 'ArrowUp') nextIdx = Math.max(idx - 4, 0);
      cells[nextIdx]?.focus();
    } else if (e.key === 'Escape') {
      setOpen(false);
    }
  };

  return <div className="slot-control">
    <span className="field-label" id="date-label">{locale === 'de' ? 'Termin auswählen' : 'Appointment date'}</span>
    <button type="button" className="picker-trigger" data-testid="slot-trigger" aria-haspopup="dialog" aria-expanded={open} aria-labelledby="date-label selected-date-label" onClick={() => setOpen(!open)}>
      <span id="selected-date-label">{selected ? selected.label : locale === 'de' ? 'Datum auswählen' : 'Choose a date'}</span><span aria-hidden="true">⌄</span>
    </button>
    {open && <div className="picker-panel" data-testid="slot-panel" role="dialog" aria-modal="true" aria-labelledby="calendar-title">
      <div className="picker-heading"><h3 id="calendar-title">{locale === 'de' ? 'November 2026' : 'November 2026'}</h3><button type="button" className="icon-button" aria-label="Close calendar" onClick={() => setOpen(false)}>×</button></div>
      <div className="calendar-week" aria-hidden="true"><span>MO</span><span>TU</span><span>WE</span><span>TH</span><span>FR</span></div>
      <div className="calendar-grid" ref={gridRef}>{choices.map((choice) => <div key={choice.date} className={`calendar-day ${choice.unavailable ? 'unavailable' : ''}`} data-date={choice.date} role="button" aria-label={choice.label} aria-disabled={choice.unavailable} tabIndex={choice.unavailable ? -1 : 0} onKeyDown={(e) => handleKeyDown(e, choice)} onClick={() => { if (!choice.unavailable) { onChange(choice.date); setOpen(false); } }}><span>{choice.day}</span><span className="availability-dot" /></div>)}</div>
      <p className="picker-hint">{locale === 'de' ? 'Alle Termine in Ihrer Ortszeit.' : 'All appointments in your local time.'}</p>
    </div>}
  </div>;
}

