import React, { useState, useRef, useEffect } from 'react';

export default function SlotControl({ value, onChange, choices, locale }) {
  const [open, setOpen] = useState(false);
  const [pendingDate, setPendingDate] = useState(null);
  const gridRef = useRef(null);
  const selected = choices.find((choice) => choice.date === value);

  // Focus first available cell when modal opens
  useEffect(() => {
    if (open && gridRef.current) {
      const focusFirst = () => {
        const firstAvailable = gridRef.current.querySelector('[data-date]:not(.unavailable)');
        if (firstAvailable) {
          firstAvailable.focus();
        } else {
          // Retry after a frame if not ready
          requestAnimationFrame(focusFirst);
        }
      };
      focusFirst();
    }
  }, [open]);

  // Listen for availability release from the test harness
  useEffect(() => {
    const handleRelease = (event) => {
      if (event.detail && event.detail.date === pendingDate) {
        onChange(pendingDate);
        setPendingDate(null);
        setOpen(false);
      }
    };
    window.addEventListener('availability.release', handleRelease);
    return () => window.removeEventListener('availability.release', handleRelease);
  }, [pendingDate, onChange]);

  const handleKeyDown = (e, choice) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (!choice.unavailable && !pendingDate) {
        // Emit pending event and wait for release
        setPendingDate(choice.date);
        window.dispatchEvent(new CustomEvent('availability.pending', { detail: { date: choice.date } }));
      }
    } else if (e.key === 'ArrowRight' || e.key === 'ArrowLeft' || e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      const cells = Array.from(gridRef.current?.querySelectorAll('[data-date]:not(.unavailable)') || []);
      const idx = cells.indexOf(e.target);
      if (idx === -1) return;
      let nextIdx = idx;
      const cols = 4; // MO, TU, WE, TH, FR, SA, SU? but we have 5 day headers? Actually 5 headers, but grid may have 7 days. We'll assume 7 columns.
      // Determine number of columns from the first row? Simpler: use 7.
      const colCount = 7;
      if (e.key === 'ArrowRight') nextIdx = (idx + 1) % cells.length;
      else if (e.key === 'ArrowLeft') nextIdx = (idx - 1 + cells.length) % cells.length;
      else if (e.key === 'ArrowDown') nextIdx = Math.min(idx + colCount, cells.length - 1);
      else if (e.key === 'ArrowUp') nextIdx = Math.max(idx - colCount, 0);
      cells[nextIdx]?.focus();
    } else if (e.key === 'Escape') {
      if (pendingDate) {
        // Cancel pending request
        setPendingDate(null);
      }
      setOpen(false);
    }
  };

  const handleModalKeyDown = (e) => {
    if (e.key === 'Tab') {
      const focusable = gridRef.current?.querySelectorAll('[data-date]:not(.unavailable), button.icon-button, [href]') || [];
      const focusableArray = Array.from(focusable);
      if (e.shiftKey) {
        // Shift+Tab: move to last focusable
        e.preventDefault();
        focusableArray[focusableArray.length - 1]?.focus();
      } else {
        // Tab: move to first focusable
        e.preventDefault();
        focusableArray[0]?.focus();
      }
    }
  };

  return (
    <div className="slot-control">
      <span className="field-label" id="date-label">{locale === 'de' ? 'Termin auswählen' : 'Appointment date'}</span>
      <button
        type="button"
        className="picker-trigger"
        data-testid="slot-trigger"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-labelledby="date-label selected-date-label"
        onClick={() => setOpen(!open)}
      >
        <span id="selected-date-label">{selected ? selected.label : locale === 'de' ? 'Datum auswählen' : 'Choose a date'}</span><span aria-hidden="true">⌄</span>
      </button>
      {open && (
        <div
          className="picker-panel"
          data-testid="slot-panel"
          role="dialog"
          aria-modal="true"
          aria-labelledby="calendar-title"
          onKeyDown={handleModalKeyDown}
        >
          <div className="picker-heading">
            <h3 id="calendar-title">{locale === 'de' ? 'November 2026' : 'November 2026'}</h3>
            <button type="button" className="icon-button" aria-label="Close calendar" onClick={() => { if (pendingDate) setPendingDate(null); setOpen(false); }}>×</button>
          </div>
          <div className="calendar-week" aria-hidden="true"><span>MO</span><span>TU</span><span>WE</span><span>TH</span><span>FR</span><span>SA</span><span>SU</span></div>
          <div className="calendar-grid" ref={gridRef}>
            {choices.map((choice) => (
              <div
                key={choice.date}
                className={`calendar-day ${choice.unavailable ? 'unavailable' : ''}`}
                data-date={choice.date}
                role="button"
                aria-label={choice.label}
                aria-disabled={choice.unavailable}
                tabIndex={choice.unavailable ? -1 : 0}
                onKeyDown={(e) => handleKeyDown(e, choice)}
                onClick={() => { if (!choice.unavailable && !pendingDate) { setPendingDate(choice.date); window.dispatchEvent(new CustomEvent('availability.pending', { detail: { date: choice.date } })); } }}
              >
                <span>{choice.day}</span>
                <span className="availability-dot" />
              </div>
            ))}
          </div>
          <p className="picker-hint">{locale === 'de' ? 'Alle Termine in Ihrer Ortszeit.' : 'All appointments in your local time.'}</p>
        </div>
      )}
    </div>
  );
}

