        e.preventDefault();
        const lastIdx = focusableArray.length - 1;
        focusableArray[lastIdx]?.focus();
      } else {
        e.preventDefault();
        focusableArray[0]?.focus();
      }
    }
  };

  return (
    <div className="slot-control">
