import React, { useState, useRef, useEffect, useMemo } from 'react';

export default function SlotControl({ value, onChange, choices, locale, checkAvailability, delayMs = 0 }) {
  const [open, setOpen] = useState(false);
  const [pendingDate, setPendingDate] = useState(null);
  const gridRef = useRef(null);
  const focusGuardRef = useRef(0);
  const selected = choices.find((choice) => choice.date === value);

  // Focus first available cell when modal opens
  useEffect(() => {
    if (!open) return;
    const guard = ++focusGuardRef.current;
    const attemptFocus = () => {
      if (guard !== focusGuardRef.current) return;
      const grid = gridRef.current;
      if (!grid) return;
      const firstAvailable = grid.querySelector('[data-date]:not(.unavailable)');
      if (firstAvailable) {
        firstAvailable.focus();
      } else {
        requestAnimationFrame(attemptFocus);
      }
    };
    requestAnimationFrame(attemptFocus);
  }, [open]);

  // Handle availability release from checkAvailability promise
  const handleReleaseRef = useRef((date) => {
    if (pendingDate === date) {
      onChange(date);
      setPendingDate(null);
      setOpen(false);
    }
  });
  handleReleaseRef.current = (date) => {
    if (pendingDate === date) {
      onChange(date);
      setPendingDate(null);
      setOpen(false);
    }
  };
  const handleRelease = useMemo(() => (date) => handleReleaseRef.current(date), []);

  const handleKeyDown = (e, choice) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (!choice.unavailable && !pendingDate) {
        setPendingDate(choice.date);
        checkAvailability(choice.date).then((result) => {
          if (result.available) {
            handleRelease(choice.date);
          } else {
            setPendingDate(null);
          }
        });
      }
    } else if (e.key === 'ArrowRight' || e.key === 'ArrowLeft' || e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      const cells = Array.from(gridRef.current?.querySelectorAll('[data-date]:not(.unavailable)') || []);
      const idx = cells.indexOf(e.target);
      if (idx === -1) return;
      const colCount = 7;
      let nextIdx = idx;
      if (e.key === 'ArrowRight') {
        nextIdx = (idx + 1) % cells.length;
      } else if (e.key === 'ArrowLeft') {
        nextIdx = (idx - 1 + cells.length) % cells.length;
      } else if (e.key === 'ArrowDown') {
        nextIdx = Math.min(idx + colCount, cells.length - 1);
      } else if (e.key === 'ArrowUp') {
        nextIdx = Math.max(idx - colCount, 0);
      }
      cells[nextIdx]?.focus();
    } else if (e.key === 'Escape') {
      if (pendingDate) {
        setPendingDate(null);
      }
      setOpen(false);
    }
  };

  const handleModalKeyDown = (e) => {
    if (e.key === 'Tab') {
      e.preventDefault();
      const focusable = gridRef.current?.querySelectorAll('[data-date]:not(.unavailable), button.icon-button, [href], button[aria-label], [role="button"][data-date]') || [];
      const focusableArray = Array.from(focusable);
      if (focusableArray.length === 0) return;
      const activeElement = document.activeElement;
      const currentIndex = focusableArray.indexOf(activeElement);
      if (e.shiftKey) {
        const nextIndex = currentIndex <= 0 ? focusableArray.length - 1 : currentIndex - 1;
        focusableArray[nextIndex]?.focus();
      } else {
        const nextIndex = currentIndex >= focusableArray.length - 1 ? 0 : currentIndex + 1;
        focusableArray[nextIndex]?.focus();
      }
    } else if (e.key === 'Escape') {
      if (pendingDate) {
        setPendingDate(null);
      }
      setOpen(false);
    }
  };

  return (
    <div className="slot-control">
      <span className="field-label" id="date-label">{locale === 'de' ? 'Termin auswählen' : 'Appointment date'}</span>
      <button
        type="button"
        className="picker-trigger"
        data-testid="slot-trigger"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-labelledby="date-label selected-date-label"
        onClick={() => setOpen(!open)}
      >
        <span id="selected-date-label">{selected ? selected.label : locale === 'de' ? 'Datum auswählen' : 'Choose a date'}</span><span aria-hidden="true">⌄</span>
      </button>
      {open && (
        <div
          className="picker-panel"
          data-testid="slot-panel"
          role="dialog"
          aria-modal="true"
          aria-labelledby="calendar-title"
          onKeyDown={handleModalKeyDown}
        >
          <div className="picker-heading">
            <h3 id="calendar-title">{locale === 'de' ? 'November 2026' : 'November 2026'}</h3>
            <button type="button" className="icon-button" aria-label="Close calendar" onClick={() => { if (pendingDate) setPendingDate(null); setOpen(false); }}>×</button>
          </div>
          <div className="calendar-week" aria-hidden="true"><span>MO</span><span>TU</span><span>WE</span><span>TH</span><span>FR</span><span>SA</span><span>SU</span></div>
          <div className="calendar-grid" ref={gridRef}>
            {choices.map((choice) => (
              <div
                key={choice.date}
                className={`calendar-day ${choice.unavailable ? 'unavailable' : ''}`}
                data-date={choice.date}
                role="button"
                aria-label={choice.label}
                aria-disabled={choice.unavailable}
                tabIndex={choice.unavailable ? -1 : 0}
                onKeyDown={(e) => handleKeyDown(e, choice)}
              >
                <span>{choice.day}</span>
                <span className="availability-dot" />
              </div>
            ))}
          </div>
          <p className="picker-hint">{locale === 'de' ? 'Alle Termine in Ihrer Ortszeit.' : 'All appointments in your local time.'}</p>
        </div>
      )}
    </div>
  );
}

